// src/components/ValidationList.jsx
import { useState, useEffect } from 'react';
import axios from 'axios';

export default function ValidationList({ token, instanceUrl }) {
  const [rules, setRules] = useState([]);

  const fetchRules = async () => {
    const query = `SELECT Id,ValidationName,Active FROM ValidationRule 
                   WHERE EntityDefinition.QualifiedApiName='Account'`;
    const res = await axios.get(
      `${instanceUrl}/services/data/v59.0/tooling/query`,
      {
        params: { q: query },
        headers: { Authorization: `Bearer ${token}` },
      }
    );
    setRules(res.data.records);
  };

  const toggleRule = async (rule) => {
    await axios.patch(
      `${instanceUrl}/services/data/v59.0/tooling/sobjects/ValidationRule/${rule.Id}`,
      { Metadata: { active: !rule.Active } },
      { headers: { Authorization: `Bearer ${token}` } }
    );
    fetchRules(); // refresh list
  };

  return (
    <div>
      <button onClick={fetchRules}>Get Validation Rules</button>
      {rules.map(rule => (
        <div key={rule.Id}>
          <span>{rule.ValidationName}</span>
          <span>{rule.Active ? '✅ Active' : '❌ Inactive'}</span>
          <button onClick={() => toggleRule(rule)}>Toggle</button>
        </div>
      ))}
    </div>
  );
}
